+    font-family: "IBM Plex Sans";
+    font-size: 16px;
+    font-weight: 600;
+    /* No background — sits on the gradient */
+    background: transparent;
+    padding: 0;
+}
+
+
+/* -----------------------------------------------------------------
+ * Version label — "4.7.0 (v4.7.0rc0-2438-g68ddfc1bcba4)"
